    std::vector<std::uint8_t> plunder_validation_source(std::size_t index)
    {
        return decode_plunder_fixture(index==0?plunder_validation_source_0_hex:plunder_validation_source_1_hex);
    }

    void island_plunder_validation_translation_checks()
    {
        namespace abi=gsc::island_plunder_validation_native_abi;
        const auto bad = [](std::string_view name, std::vector<std::uint8_t> code)
        {
            const auto baseline=code;
            Check(!abi::translate_private_compiler_copy(name,code) && code==baseline,
                "Plunder validation ABI accepted or partially modified unknown bytecode");
        };
        for(std::size_t i=0;i<abi::source_profiles.size();++i)
        {
            const auto& profile=abi::source_profiles[i];
            const auto source=plunder_validation_source(i);
            Check(source.size()==profile.source_length && abi::fingerprint(source)==profile.source_fingerprint,
                "Plunder validation fixture/source checksum mismatch");
            bad("scripts/mp/validation.gsc",source);
            bad("1923",source);
            bad("2379",source);
            bad(profile.module,{});
            auto short_code=source; short_code.pop_back(); bad(profile.module,short_code);
            auto long_code=source; long_code.push_back(0); bad(profile.module,long_code);
            for(const std::size_t at:{std::size_t(0),source.size()-1})
            {
                auto changed=source;changed[at]^=1;bad(profile.module,changed);
            }
            for(const auto& site:profile.calls)
                for(std::size_t at=site.offset;at<site.offset+3;++at)
                {
                    auto changed=source;changed[at]^=1;bad(profile.module,changed);
                }
            auto translated=source;
            Check(abi::translate_private_compiler_copy(profile.module,translated),
                "Plunder validation ABI rejected genuine installed numeric module");
            Check(abi::fingerprint(translated)==profile.replay_fingerprint,
                "Plunder validation ABI result fingerprint differs");
            std::size_t changed_count{};
            for(std::size_t at=0;at<source.size();++at)
            {
                if(source[at]==translated[at])continue;
                bool expected=false;
                for(const auto& site:profile.calls)
                {
                    expected |= at==site.offset+1 && source[at]==std::uint8_t(site.source_id) &&
                        translated[at]==std::uint8_t(site.replay_id);
                }
                Check(expected,"Plunder validation ABI changed an unrelated code byte");
                ++changed_count;
            }
            Check(changed_count==profile.calls.size(),"Plunder validation did not change every verified opcode");
            bad(profile.module,translated);
            auto failed_target=source;
            Check(!abi::translate_exact_profile(profile,failed_target,profile.source_fingerprint,
                profile.replay_fingerprint^1) && failed_target==source,
                "Plunder validation failed to roll back a mismatched target fingerprint");
        }
    }
